def antipode_test(vectors: list[list[float]], *, threshold: float = 0.0) -> tuple[int, list[int]]:
    import math
    # Compute centroid
    n_vectors = len(vectors)
    if n_vectors == 0:
        return 0, []
    dimension = len(vectors[0])
    centroid = [0.0] * dimension
    for v in vectors:
        for i in range(dimension):
            centroid[i] += v[i]
    centroid = [x / n_vectors for x in centroid]

    def dot(a, b):
        return sum(x * y for x, y in zip(a, b))

    def norm(a):
        return math.sqrt(dot(a, a))

    centroid_norm = norm(centroid)
    # Handle case where centroid is zero vector
    if centroid_norm == 0:
        cosine_similarities = [0.0 for _ in vectors]
    else:
        cosine_similarities = []
        for v in vectors:
            v_norm = norm(v)
            if v_norm == 0:
                cosine_similarities.append(0.0)
            else:
                cosine_similarities.append(dot(v, centroid) / (v_norm * centroid_norm))
    # Calculate adaptive mean
    mean_score = sum(cosine_similarities) / n_vectors
    # Count and collect indices of vectors at or above the threshold
    count = 0
    indices = []
    for i, score in enumerate(cosine_similarities):
        if score >= max(threshold, mean_score):
            count += 1
            indices.append(i)
    return count, indices
